 set SQL_SAFE_UPDATES=0;
    UPDATE `EMAIL_SCENARIO` SET `SUBJECT`='New job has been assigned to you, {{AssignToTeamMembers.RequirementTitle}}.', `BODY`='Dear {{AssignToTeamMembers.Ownername}},\n\n{{AssignToTeamMembers.LoginUser}} has assigned you a new Job\nPlease find the details below.\nJob Title :{{AssignToTeamMembers.RequirementTitle}}\nJob Location :{{AssignToTeamMembers.RequirementLocation}} \nJob Rate :{{AssignToTeamMembers.RequirementRate}}\nExperience :{{AssignToTeamMembers.Experience}}\nNo of Positions : {{RequirementPosting.positions}}\nPriority : {{RequirementPosting.priority}}\nSkills : {{RequirementPosting.skills}}\nDescription : {{RequirementPosting.description}}\nManager :{{AssignToTeamMembers.manager}}\n\nFor more details login into the system\n {{AssignToTeamMembers.link}}',`SIGNATURE`= 'Best Regards\n {{AssignToTeamMembers.LoginUser}}' WHERE `UNIQUE_SCENARIO_NAME`='AssignToTeamMembers' and `ENTITY_TYPE`='Email';
SET SQL_SAFE_UPDATES = 1;